#include <bits/stdc++.h>
using namespace std;

const long long INF = 1e18;
unordered_map<long long, long long> memo;

long long solve(long long n) {
    if (n == 0) return 0;

    auto it = memo.find(n);
    if (it != memo.end()) return it->second;

    long long lastDiff = INF;
    long long x = 1, i = 0;

    while (abs(x - n) <= lastDiff) {
        lastDiff = abs(x - n);
        x = x * 10 + 1;
        ++i;
    }

    x /= 10;

    long long result;
    if (x > n && x / 10) {
        result = min(i + solve(x - n),
                     i - 1 + solve(n - x / 10));
    } else {
        result = i + solve(abs(x - n));
    }

    return memo[n] = result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;

    cout << solve(n);
    return 0;
}

