#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

unordered_map<int64, int64> memo;

int64 solve(int64 n) {
    if (n == 0) return 0;

    auto it = memo.find(n);
    if (it != memo.end()) return it->second;

    i128 x = 1;
    i128 lastDiff = (i128(1) << 126);
    int64 digits = 0;

    while (true) {
        i128 diff = x >= n ? x - n : n - x;
        if (diff > lastDiff) break;
        lastDiff = diff;
        x = x * 10 + 1;
        ++digits;
    }

    x /= 10;

    auto difference = [n](i128 value) -> int64 {
        i128 diff = value >= n ? value - n : n - value;
        return static_cast<int64>(diff);
    };

    int64 result;
    if (x > n && x / 10 != 0) {
        result = min(digits + solve(difference(x)),
                     digits - 1 + solve(difference(x / 10)));
    } else {
        result = digits + solve(difference(x));
    }

    return memo[n] = result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n;
    cin >> n;

    memo.reserve(1024);
    cout << solve(n);
    return 0;
}

